def specialFilter(nums):
    count = 0
    for num in nums:
        if num <= 10:
            continue
        last_digit = num % 10
        n = num
        while n >= 10:
            n = n // 10
        first_digit = n
        if first_digit % 2 == 1 and last_digit % 2 == 1:
            count += 1
    return count
